--
-- Estrutura para view `v_attendance_receipts`
--
DROP TABLE IF EXISTS `v_attendance_receipts`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_attendance_receipts`  AS SELECT `a`.`id` AS `id`, `a`.`nsr` AS `nsr`, `a`.`teacher_id` AS `teacher_id`, `t`.`name` AS `teacher_name`, `t`.`cpf` AS `teacher_cpf`, `a`.`date` AS `date`, `a`.`check_in` AS `check_in`, `a`.`check_out` AS `check_out`, CASE WHEN `a`.`check_out` is not null THEN 'saida' ELSE 'entrada' END AS `action`, `a`.`record_mode` AS `record_mode`, `a`.`recorded_at` AS `recorded_at`, `a`.`synced_at` AS `synced_at`, `a`.`check_in_lat` AS `latitude`, `a`.`check_in_lng` AS `longitude`, `a`.`photo` AS `photo`, `a`.`approved` AS `approved`, `a`.`hlb_sync_status` AS `hlb_sync_status`, `a`.`device_identifier` AS `device_identifier`, `a`.`receipt_generated` AS `receipt_generated`, `a`.`receipt_viewed_at` AS `receipt_viewed_at`, `e`.`company_name` AS `company_name`, `e`.`cnpj` AS `cnpj`, `e`.`system_name` AS `system_name`, `e`.`system_version` AS `system_version`, `e`.`rep_category` AS `rep_category` FROM ((`attendance` `a` join `teachers` `t` on(`a`.`teacher_id` = `t`.`id`)) join `employer_config` `e`) ORDER BY `a`.`nsr` DESC ;

-- --------------------------------------------------------

--
-- Estrutura para view `v_calendar_full`
--
DROP TABLE IF EXISTS `v_calendar_full`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_calendar_full`  AS SELECT `ce`.`id` AS `id`, `ce`.`date` AS `date`, `ce`.`type` AS `type`, `ce`.`name` AS `name`, `ce`.`description` AS `description`, `ce`.`is_working_day` AS `is_working_day`, `ce`.`recurrence` AS `recurrence`, `ce`.`school_id` AS `school_id`, `s`.`name` AS `school_name`, `s`.`name` AS `end` FROM (`calendar_exceptions` `ce` left join `schools` `s` on(`s`.`id` = `ce`.`school_id`)) ORDER BY `ce`.`date` DESC ;

-- --------------------------------------------------------

--
-- Estrutura para view `v_fraud_analysis`
--
DROP TABLE IF EXISTS `v_fraud_analysis`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_fraud_analysis`  AS SELECT `t`.`id` AS `teacher_id`, `t`.`name` AS `teacher_name`, count(distinct cast(`fdl`.`created_at` as date)) AS `suspicious_days`, count(`fdl`.`id`) AS `total_detections`, sum(case when `fdl`.`detection_type` = 'gps_mock' then 1 else 0 end) AS `mock_count`, sum(case when `fdl`.`risk_level` >= 2 then 1 else 0 end) AS `high_risk_count`, max(`fdl`.`created_at`) AS `last_detection` FROM (`teachers` `t` left join `fraud_detection_log` `fdl` on(`fdl`.`teacher_id` = `t`.`id`)) WHERE `fdl`.`created_at` >= current_timestamp() - interval 30 day GROUP BY `t`.`id`, `t`.`name` HAVING `total_detections` > 0 ORDER BY sum(case when `fdl`.`risk_level` >= 2 then 1 else 0 end) DESC, count(`fdl`.`id`) DESC ;

-- --------------------------------------------------------

--
-- Estrutura para view `v_payslips_full`
--
DROP TABLE IF EXISTS `v_payslips_full`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_payslips_full`  AS SELECT `p`.`id` AS `id`, `p`.`reference_month` AS `reference_month`, date_format(`p`.`reference_month`,'%m/%Y') AS `month_formatted`, year(`p`.`reference_month`) AS `year`, `p`.`teacher_id` AS `teacher_id`, `t`.`name` AS `teacher_name`, `t`.`cpf` AS `teacher_cpf`, `p`.`base_salary` AS `base_salary`, `p`.`worked_minutes` AS `worked_minutes`, `p`.`expected_minutes` AS `expected_minutes`, `p`.`overtime_minutes` AS `overtime_minutes`, `p`.`overtime_value` AS `overtime_value`, `p`.`deficit_minutes` AS `deficit_minutes`, `p`.`discount_value` AS `discount_value`, `p`.`gross_total` AS `gross_total`, `p`.`net_total` AS `net_total`, `p`.`generated_at` AS `generated_at`, `p`.`viewed_by_teacher_at` AS `viewed_by_teacher_at`, CASE WHEN `p`.`viewed_by_teacher_at` is not null THEN 1 ELSE 0 END AS `was_viewed` FROM (`payslips` `p` join `teachers` `t` on(`t`.`id` = `p`.`teacher_id`)) ORDER BY `p`.`reference_month` DESC, `t`.`name` ASC ;

